// HTML: <button id="btn">Davom etish</button>
const btn = document.getElementById("btn");

function waitFor(target, type) {
    return new Promise((resolve) => {
        target.addEventListener(type, resolve, { once: true });
    });
}

async function run() {
    console.log("tugma bosilishini kutyapmiz...");
    const event = await waitFor(btn, "click");
    console.log("kutilgan hodisa keldi:", event.type);
}

run();
btn.click(); // foydalanuvchi bosdi

// HTML: <button id="inc">+</button><button id="dec">-</button>
class Counter {
    #value = 0;
    #controller = new AbortController();

    mount() {
        const { signal } = this.#controller;
        document.getElementById("inc").addEventListener("click", () => this.#change(1), { signal });
        document.getElementById("dec").addEventListener("click", () => this.#change(-1), { signal });
    }

    #change(step) {
        this.#value += step;
        console.log("qiymat:", this.#value);
    }

    unmount() {
        this.#controller.abort();
    }
}

const counter = new Counter();
counter.mount();
document.getElementById("inc").click();
document.getElementById("inc").click();
document.getElementById("dec").click();
counter.unmount();
document.getElementById("inc").click(); // endi hech narsa bo'lmaydi
console.log("komponent yopildi");

