// HTML: <ul id="list"><li id="item"><b><i id="deep">Olma</i></b></li></ul>
function findAncestor(element, selector) {
    let current = element;
    while (current) {
        if (current.matches(selector)) return current;
        current = current.parentElement;
    }
    return null;
}

const deep = document.getElementById("deep");
console.log(findAncestor(deep, "li").id);
console.log(findAncestor(deep, "ul").id);
console.log(findAncestor(deep, "table"));
console.log(deep.closest("li") === findAncestor(deep, "li"));

class Tree {
    constructor(name, parent = null) {
        this.name = name;
        this.parent = parent;
    }
}

const root = new Tree("window");
const body = new Tree("body", root);
const card = new Tree("card", body);
const button = new Tree("button", card);

function pathOf(node) {
    const path = [];
    for (let current = node; current; current = current.parent) {
        path.push(current.name);
    }
    return path;
}

console.log(pathOf(button).join(" -> "));
console.log(pathOf(card).join(" -> "));

class Item {
    constructor(name, parent = null) {
        this.name = name;
        this.parent = parent;
        this.listeners = [];
    }
    on(handler, capture = false) {
        this.listeners.push({ handler, capture });
    }
}

function dispatch(target) {
    const path = [];
    for (let item = target; item; item = item.parent) path.unshift(item);
    const ancestors = path.slice(0, -1);
    for (const item of ancestors) {
        item.listeners.filter((l) => l.capture).forEach((l) => l.handler(item, "capturing"));
    }
    target.listeners.forEach((l) => l.handler(target, "target"));
    for (const item of ancestors.reverse()) {
        item.listeners.filter((l) => !l.capture).forEach((l) => l.handler(item, "bubbling"));
    }
}

const body = new Item("body");
const card = new Item("card", body);
const button = new Item("button", card);
for (const item of [body, card]) {
    item.on((n, phase) => console.log(n.name, phase), true);
    item.on((n, phase) => console.log(n.name, phase));
}
button.on((n, phase) => console.log(n.name, phase));
dispatch(button);

const tree = {
    name: "ul", parent: null,
    items: [],
};
const makeItem = (id) => {
    const li = { name: "li", id, parent: tree };
    const span = { name: "span", id: `${id}-text`, parent: li };
    tree.items.push(li);
    return span;
};

function closest(node, name) {
    for (let current = node; current; current = current.parent) {
        if (current.name === name) return current;
    }
    return null;
}

const clickTargets = [makeItem("a"), makeItem("b"), tree];
for (const target of clickTargets) {
    const item = closest(target, "li");
    console.log(target.name, "->", item ? `li#${item.id}` : "li topilmadi");
}

