    if (e.shiftKey) console.log("Shift + click");
});

let dx = 0, dy = 0;
ball.addEventListener("pointerdown", (e) => {
    ball.setPointerCapture(e.pointerId);    // sichqoncha tashqariga chiqsa ham hodisa shu yerga keladi
    dx = e.clientX - ball.offsetLeft;
    dy = e.clientY - ball.offsetTop;
});
ball.addEventListener("pointermove", (e) => {
    if (!ball.hasPointerCapture(e.pointerId)) return;
    ball.style.left = e.clientX - dx + "px";
    ball.style.top = e.clientY - dy + "px";
});

document.addEventListener("keydown", (e) => {
    const mod = e.ctrlKey || e.metaKey;            // Windows: Ctrl, Mac: Cmd
