const items = [...files.children];
let last = 0;

files.addEventListener("click", (event) => {
    const index = items.indexOf(event.target);
    if (index === -1) return;
    if (!event.shiftKey) {
        items.forEach((li) => li.classList.remove("selected"));
        last = index;
    }
    const [from, to] = [Math.min(last, index), Math.max(last, index)];
    items.slice(from, to + 1).forEach((li) => li.classList.add("selected"));
    console.log("tanlangan:", items.filter((li) => li.classList.contains("selected")).map((li) => li.textContent).join(", "));
});

items[1].dispatchEvent(new MouseEvent("click", { bubbles: true }));                   // oddiy click
items[3].dispatchEvent(new MouseEvent("click", { bubbles: true, shiftKey: true }));  // Shift + click

