// HTML: <div id="ball" style="position:absolute; left:0; top:0; width:50px; height:50px; background:#f66; touch-action:none"></div>
const ball = document.getElementById("ball");
let grabX = 0;
let grabY = 0;

ball.addEventListener("pointerdown", (event) => {
    ball.setPointerCapture(event.pointerId);
    grabX = event.clientX - ball.offsetLeft;
    grabY = event.clientY - ball.offsetTop;
});
ball.addEventListener("pointermove", (event) => {
    if (!ball.hasPointerCapture(event.pointerId)) return;
    ball.style.left = event.clientX - grabX + "px";
    ball.style.top = event.clientY - grabY + "px";
});
ball.addEventListener("pointerup", () => {
    console.log("qo'yib yuborildi:", ball.style.left, ball.style.top);
});
