// HTML: <div id="area" style="position:absolute; left:50px; top:50px; width:300px; height:200px; background:#eef"><div id="ball" style="position:absolute; left:0; top:0; width:50px; height:50px; background:#f66; touch-action:none"></div></div>
const area = document.getElementById("area");
const ball = document.getElementById("ball");
let grabX = 0;
let grabY = 0;

ball.addEventListener("pointerdown", (event) => {
    ball.setPointerCapture(event.pointerId);
    grabX = event.clientX - ball.getBoundingClientRect().left;
    grabY = event.clientY - ball.getBoundingClientRect().top;
});
ball.addEventListener("pointermove", (event) => {
    if (!ball.hasPointerCapture(event.pointerId)) return;
    const box = area.getBoundingClientRect();
    const x = event.clientX - box.left - grabX;
    const y = event.clientY - box.top - grabY;
    ball.style.left = Math.min(Math.max(x, 0), area.clientWidth - ball.offsetWidth) + "px";
    ball.style.top = Math.min(Math.max(y, 0), area.clientHeight - ball.offsetHeight) + "px";
});
ball.addEventListener("pointerup", () => console.log("oxirgi joy:", ball.style.left, ball.style.top));
