function describeCombo(event) {
    const parts = [];
    if (event.ctrlKey || event.metaKey) parts.push("Ctrl");
    if (event.altKey) parts.push("Alt");
    if (event.shiftKey) parts.push("Shift");
    parts.push(event.key.length === 1 ? event.key.toUpperCase() : event.key);
    return parts.join("+");
}

const events = [
    { key: "s", ctrlKey: true },
    { key: "k", ctrlKey: true, shiftKey: true },
    { key: "Escape" },
    { key: "z", metaKey: true, altKey: true },
];
for (const event of events) {
    console.log(describeCombo(event));
}

const secret = ["ArrowUp", "ArrowUp", "ArrowDown", "ArrowDown", "b", "a"];

function createDetector(onMatch) {
    let index = 0;
    return (event) => {
        if (event.key === secret[index]) {
            index += 1;
        } else {
            index = event.key === secret[0] ? 1 : 0;
        }
        if (index === secret.length) {
            index = 0;
            onMatch();
        }
    };
}

const detect = createDetector(() => console.log("Konami kodi topildi!"));
const keys = ["ArrowUp", "ArrowUp", "ArrowDown", "x", "ArrowUp", "ArrowUp", "ArrowDown", "ArrowDown", "b", "a"];
for (const key of keys) {
    detect({ key });
}
console.log("tugadi");

function createDoubleClickDetector(maxGap = 300) {
    let last = -Infinity;
    return (time) => {
        const isDouble = time - last <= maxGap;
        last = isDouble ? -Infinity : time;
        return isDouble;
    };
}

const isDouble = createDoubleClickDetector(300);
for (const time of [0, 200, 1000, 1500, 1600, 2500]) {
    console.log(`${time} ms ->`, isDouble(time) ? "ikki marta bosish" : "bitta bosish");
}

function createDragDetector(threshold = 5) {
    let start = null;
    return {
        down(x, y) {
            start = { x, y };
        },
        move(x, y) {
            if (!start) return "bosilmagan";
            const distance = Math.hypot(x - start.x, y - start.y);
            return distance > threshold ? `sudrash (${distance.toFixed(1)} px)` : `titrash (${distance.toFixed(1)} px)`;
        },
    };
}

