        const { signal } = this.#controller;
        document.getElementById("inc").addEventListener("click", () => {
            this.#count += 1;
            console.log("tugma:", this.#count);
        }, { signal });
        document.addEventListener("theme:change", (event) => {
            console.log("tema:", event.detail);
        }, { signal });
    }

    unmount() {
        this.#controller.abort();
    }
}

const counter = new Counter();
counter.mount();
document.getElementById("inc").click();
document.dispatchEvent(new CustomEvent("theme:change", { detail: "qorong'i" }));

counter.unmount();
document.getElementById("inc").click();
document.dispatchEvent(new CustomEvent("theme:change", { detail: "yorug'" }));
console.log("komponent yopildi, tinglovchilar tozalandi");
